INSERT INTO public.questions (material_id, soal, pilihan, jawaban_benar, level, penjelasan) VALUES

-- k6-mtk-10
('k6-mtk-10', 'Bentuk rasio satuan dari 10:50 adalah...', '{"a":"1:5","b":"2:10","c":"5:1","d":"10:1"}', 'a', 1, 'Bagi kedua angka dengan 10.'),
('k6-mtk-10', 'Bentuk rasio satuan dari 100:25 adalah...', '{"a":"1:4","b":"4:1","c":"2:1","d":"5:1"}', 'b', 1, 'Bagi kedua angka dengan 25.'),
('k6-mtk-10', 'Andi lari 15 km dalam 3 jam. Rasio jarak:waktu dalam bentuk satuan?', '{"a":"15:1","b":"1:5","c":"5:1","d":"3:1"}', 'c', 2, '15/3 = 5 km per 1 jam, jadi 5:1.'),
('k6-mtk-10', 'Beli 4 pensil harga Rp 8.000. Rasio Rp:pensil adalah?', '{"a":"8000:4","b":"2000:1","c":"1:2000","d":"4:8000"}', 'b', 2, '8000 dibagi 4 = 2000 per 1 pensil.'),
('k6-mtk-10', 'Mesin cuci butuh 15 liter air untuk 3 kg baju. Berapa liter air untuk 1 kg baju?', '{"a":"3 liter","b":"4 liter","c":"5 liter","d":"6 liter"}', 'c', 3, '15 : 3 = 5 : 1. Artinya 5 liter per 1 kg.'),

-- k6-mtk-11
('k6-mtk-11', 'Laki:Perempuan = 1:2. Total 15 siswa. Berapa siswa laki-laki?', '{"a":"5","b":"10","c":"15","d":"3"}', 'a', 1, 'Total bagian 1+2=3. Laki-laki 1/3 x 15 = 5.'),
('k6-mtk-11', 'Sapi:Kambing = 3:4. Total hewan 21. Berapa Kambing?', '{"a":"9","b":"12","c":"15","d":"10"}', 'b', 1, '4/7 x 21 = 12.'),
('k6-mtk-11', 'Uang Andi:Budi:Cici = 1:2:3. Total uang Rp 60.000. Uang Budi?', '{"a":"10.000","b":"20.000","c":"30.000","d":"40.000"}', 'b', 2, 'Total bagian = 6. Budi = 2/6 x 60.000 = 20.000.'),
('k6-mtk-11', 'A:B = 2:3. Selisihnya 10. Berapa nilai A?', '{"a":"10","b":"20","c":"30","d":"50"}', 'b', 2, 'Selisih rasio 1 bagian = 10. Maka A = 2 bagian = 20.'),
('k6-mtk-11', 'Resep sirup: Air:Gula:Melon = 5:2:3. Total 20 liter sirup. Berapa liter Air?', '{"a":"5","b":"10","c":"12","d":"15"}', 'b', 3, 'Total rasio 10. Air = 5/10 x 20 = 10 liter.'),

-- k6-mtk-12
('k6-mtk-12', 'Rasio 1 jam : 120 menit adalah?', '{"a":"1:120","b":"1:2","c":"2:1","d":"60:1"}', 'b', 1, '1 jam = 60 menit. 60:120 = 1:2.'),
('k6-mtk-12', 'Rasio 30 detik : 1 menit adalah?', '{"a":"30:1","b":"1:2","c":"2:1","d":"1:30"}', 'b', 1, '1 menit = 60 detik. 30:60 = 1:2.'),
('k6-mtk-12', 'Mobil A jalan 60 km dalam 2 jam. Kecepatannya?', '{"a":"30 km/jam","b":"60 km/jam","c":"120 km/jam","d":"20 km/jam"}', 'a', 2, '60 dibagi 2 = 30.'),
('k6-mtk-12', 'Andi mengetik 200 kata dalam 4 menit. Kecepatannya?', '{"a":"20 kata/menit","b":"50 kata/menit","c":"100 kata/menit","d":"400 kata/menit"}', 'b', 2, '200 / 4 = 50.'),
('k6-mtk-12', 'Rina menempuh 120 km dalam 1.5 jam. Budi menempuh 100 km dalam 1 jam. Siapa yang kecepatannya lebih tinggi?', '{"a":"Rina","b":"Budi","c":"Sama","d":"Tidak tahu"}', 'b', 3, 'Rina = 120/1.5 = 80 km/jam. Budi = 100 km/jam. Budi lebih tinggi.'),

-- k6-mtk-13
('k6-mtk-13', 'Berapa banyak titik sudut pada balok?', '{"a":"6","b":"8","c":"12","d":"10"}', 'b', 1, 'Balok punya 8 titik sudut yang melancip di ujung-ujungnya.'),
('k6-mtk-13', 'Sisi-sisi pada kubus semuanya berbentuk?', '{"a":"Persegi panjang","b":"Segitiga","c":"Persegi","d":"Lingkaran"}', 'c', 1, 'Kubus adalah bangun sempurna dengan sisi persegi.'),
('k6-mtk-13', 'Jaring-jaring balok terdiri dari berapa buah persegi panjang?', '{"a":"4","b":"6","c":"8","d":"12"}', 'b', 2, 'Ada 6 bidang sisi pembentuk balok.'),
('k6-mtk-13', 'Manakah benda di bawah ini yang bentuknya balok?', '{"a":"Dadu","b":"Bola tenis","c":"Kotak susu","d":"Piramida"}', 'c', 2, 'Kotak susu memanjang, berbeda dengan dadu yang semua sisinya sama.'),
('k6-mtk-13', 'Jika panjang semua rusuk kubus digabung adalah 120 cm, berapa panjang satu rusuknya?', '{"a":"10 cm","b":"12 cm","c":"20 cm","d":"6 cm"}', 'a', 3, 'Kubus punya 12 rusuk. 120 / 12 = 10 cm.'),

-- k6-mtk-14
('k6-mtk-14', 'Dilihat dari atas, bentuk sebuah balok terlihat seperti...', '{"a":"Segitiga","b":"Persegi Panjang","c":"Lingkaran","d":"Garis"}', 'b', 1, 'Alas/atap balok berbentuk persegi panjang.'),
('k6-mtk-14', 'Dilihat dari sisi mana pun, kubus akan terlihat sebagai...', '{"a":"Persegi Panjang","b":"Lingkaran","c":"Persegi","d":"Segitiga"}', 'c', 1, 'Semua sisinya persegi.'),
('k6-mtk-14', 'Balok dengan P=10, L=5, T=4. Ukuran tampak atasnya adalah?', '{"a":"10 x 5","b":"10 x 4","c":"5 x 4","d":"2 x 2"}', 'a', 2, 'Dari atas, yang terlihat adalah Panjang dan Lebar.'),
('k6-mtk-14', 'Balok dengan P=8, L=6, T=5. Ukuran tampak depannya?', '{"a":"8 x 6","b":"8 x 5","c":"6 x 5","d":"Tidak tahu"}', 'b', 2, 'Dari depan, terlihat Panjang dan Tinggi.'),
('k6-mtk-14', 'Tampak depan dan tampak atas sebuah kubus ternyata memiliki luas yang...', '{"a":"Berbeda","b":"Sama persis","c":"Terkadang sama","d":"Lebih besar atas"}', 'b', 3, 'Kubus sisinya identik (sama).'),

-- k6-mtk-15
('k6-mtk-15', 'Titik (4, 1) berarti...', '{"a":"Baris 4, kolom 1","b":"Kolom 4, baris 1","c":"Naik 4, turun 1","d":"Kanan 1, atas 4"}', 'b', 1, 'Koordinat itu (X, Y) alias (Kanan/Kolom, Atas/Baris).'),
('k6-mtk-15', 'Andi di (2,2), dia bergeser ke kanan 3 langkah. Di manakah posisinya sekarang?', '{"a":"(5, 2)","b":"(2, 5)","c":"(5, 5)","d":"(0, 0)"}', 'a', 1, 'Geser kanan berarti nilai X (kolom) tambah 3.'),
('k6-mtk-15', 'Dari (1, 1) menuju (1, 5) artinya...', '{"a":"Kanan 4 langkah","b":"Kiri 4 langkah","c":"Atas 4 langkah","d":"Bawah 4 langkah"}', 'c', 2, 'Nilai Y naik dari 1 ke 5.'),
('k6-mtk-15', 'Posisi awal (3,3). Jalan ke kiri 2 langkah, turun 1 langkah. Posisi akhir?', '{"a":"(5,4)","b":"(1,2)","c":"(2,1)","d":"(1,4)"}', 'b', 2, 'X: 3-2=1. Y: 3-1=2.'),
('k6-mtk-15', 'Titik A(1,1), B(4,1), C(4,4), D(1,4) dihubungkan. Akan jadi bangun apa?', '{"a":"Persegi panjang","b":"Persegi","c":"Segitiga","d":"Garis"}', 'b', 3, 'Panjang sisinya sama-sama 3 satuan kotak.'),

-- k6-mtk-16
('k6-mtk-16', 'Peluang suatu kejadian yang mustahil adalah?', '{"a":"-1","b":"0","c":"0.5","d":"1"}', 'b', 1, 'Peluang terkecil adalah 0.'),
('k6-mtk-16', 'Peluang sebuah kejadian yang "Pasti Terjadi" bernilai?', '{"a":"0","b":"1","c":"10","d":"100"}', 'b', 1, 'Peluang terbesar dalam probabilitas adalah 1 (atau 100%).'),
('k6-mtk-16', 'Peluang munculnya kiamat esok hari (kira-kira) masuk kategori?', '{"a":"Pasti","b":"Mungkin","c":"Hampir Mustahil","d":"Sering"}', 'c', 2, 'Sangat kecil peluangnya.'),
('k6-mtk-16', 'Ada 2 bola merah, 3 bola hijau di kantong. Peluang terambil bola merah?', '{"a":"2/3","b":"3/5","c":"2/5","d":"1/2"}', 'c', 2, 'Merah dibagi Total. 2 / (2+3) = 2/5.'),
('k6-mtk-16', 'Dari 10 soal, Andi bisa jawab benar 9. Peluang soal dijawab benar adalah?', '{"a":"0.1","b":"0.9","c":"1.0","d":"0.5"}', 'b', 3, '9/10 = 0.9. Ini "Hampir Pasti".'),

-- k6-mtk-17
('k6-mtk-17', 'Berapa peluang muncul Angka pada koin yang dilempar?', '{"a":"1/4","b":"1/3","c":"1/2","d":"1"}', 'c', 1, 'Koin punya 2 sisi, Angka dan Gambar. Jadi 1/2.'),
('k6-mtk-17', 'Berapa peluang muncul mata dadu 6?', '{"a":"1/6","b":"6/6","c":"1/2","d":"1/3"}', 'a', 1, 'Dadu ada 6 angka. Mata 6 hanya 1 bagian.'),
('k6-mtk-17', 'Peluang dadu menunjukkan angka GANJIL adalah?', '{"a":"1/6","b":"2/6","c":"3/6 (1/2)","d":"4/6"}', 'c', 2, 'Angka ganjil di dadu: 1, 3, 5. Jadi 3/6.'),
('k6-mtk-17', 'Mana yang lebih besar peluangnya: Lempar koin dapat GAMBAR atau lempar dadu dapat angka 1?', '{"a":"Dadu","b":"Koin","c":"Sama saja","d":"Tidak tahu"}', 'b', 2, 'Koin = 1/2. Dadu = 1/6. 1/2 lebih besar.'),
('k6-mtk-17', 'Dalam kartu remi (52 kartu), peluang ambil kartu warna MERAH adalah?', '{"a":"1/4","b":"1/2","c":"1/13","d":"1/52"}', 'b', 3, 'Separuh kartu hitam, separuh merah. Peluangnya 1/2.'),

-- k6-mtk-18
('k6-mtk-18', 'Peluang hujan hari ini 90%. Apa yang sebaiknya dilakukan?', '{"a":"Bawa jas hujan/payung","b":"Cuci motor","c":"Jemur pakaian tebal","d":"Main di lapangan"}', 'a', 1, '90% sangat tinggi, kemungkinan besar hujan.'),
('k6-mtk-18', 'Peluang Budi telat karena jalanan kosong adalah 5%. Apa artinya?', '{"a":"Budi pasti telat","b":"Budi hampir mustahil telat","c":"Budi sering telat","d":"Budi 5 kali telat"}', 'b', 1, '5% sangat kecil.'),
('k6-mtk-18', 'Di kantin ada 5 mie ayam, 15 nasi goreng. Peluang pelanggan selanjutnya pesan nasi goreng?', '{"a":"15/20 (3/4)","b":"5/20 (1/4)","c":"15/5 (3)","d":"1/2"}', 'a', 2, 'Mayoritas suka nasi goreng, rasionya 15 dari 20.'),
('k6-mtk-18', 'Peluang mesin A rusak 1/100, mesin B rusak 1/50. Mesin mana yang lebih bagus?', '{"a":"Mesin A","b":"Mesin B","c":"Sama","d":"Tidak bisa dibandingkan"}', 'a', 2, 'Peluang rusak Mesin A lebih kecil (1/100 < 1/50).'),
('k6-mtk-18', 'Anton mencoba ikut undian yang peluang menangnya 1 dari sejuta. Artinya?', '{"a":"Ia pasti menang besok","b":"Sebaiknya ia tidak berharap menang","c":"Peluangnya besar","d":"Ia akan menang setelah 1 juta kali main"}', 'b', 3, 'Sangat mustahil / hampir mustahil terjadi.');
